// Data shape: state { items: Array<{ id: number, name: string }> }
// Data shape: actions { add: (name: string) => void }
const ActionsContext = createContext(null);
const StateContext = createContext(null);

function Provider({ children }) {
    const [state, dispatch] = useReducer(reducer, { items: [] });
    const add = useCallback((name) => dispatch({ type: 'add', name }), []);
    const actions = useMemo(() => ({ add }), [add]);

    return (
        <ActionsContext.Provider value={actions}>
            <StateContext.Provider value={state}>{children}</StateContext.Provider>
        </ActionsContext.Provider>
    );
}

// Fallback that works without a provider
const LocaleContext = createContext('en');

function Standalone() {
    const locale = useContext(LocaleContext);
    return <p>{locale}</p>; // 'en'
}

function Wrapped() {
    return (
        <LocaleContext.Provider value="de">
            <Standalone /> {/* 'de' */}
        </LocaleContext.Provider>
    );
}

function App() {
    return (
        <ThemeContext.Provider value="light">
            <Page />
            <ThemeContext.Provider value="dark">
                <Preview /> {/* reads "dark" */}
            </ThemeContext.Provider>
        </ThemeContext.Provider>
    );
}

function Provider({ children }) {
    const [dark, setDark] = useState(false);

    const toggle = useCallback(() => setDark((old) => !old), []);

    // Without useMemo the object below is new on every render
    const value = useMemo(() => ({ dark, toggle }), [dark, toggle]);

    return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

import { memo } from 'react';

const RoomRow = memo(function RoomRow({ room, onSelect }) {
    return (
        <li>
            {room.name}
            <button onClick={() => onSelect(room.id)}>Open</button>
        </li>
    );
});

// Parent must pass stable props or this does nothing:
// <RoomRow room={room} onSelect={selectRoom} />

const Row = memo(
    function Row({ room, onSelect }) {
        return <li onClick={() => onSelect(room.id)}>{room.name}</li>;
    },
    (prev, next) => prev.room.id === next.room.id && prev.onSelect === next.onSelect
);

const visible = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return rooms;
    return rooms.filter((room) => room.name.toLowerCase().includes(needle));
}, [rooms, query]);

body:
Worth it when the calculation grows with the data or when the result is a prop of a memoized child. Not worth it for a single arithmetic expression.

Never put a side effect inside: no `setState`, no fetch, no storage write. React may drop the cached value and run the function again.

```jsx
// Sort a copy, because sort mutates
const sorted = useMemo(() => [...rooms].sort((a, b) => a.price - b.price), [rooms]);
```

